dados coletados:
{{ $json.informacao_resumida_desse_subtopico }}

parameters.jsCode:
// 1. Pega os 13 subtópicos oficiais da status_pesquisa
const subtopicosOriginais = $('obtem items com status auditar').all();

if (subtopicosOriginais.length === 0) {
  return [];
}

// 2. Pega as linhas garimpadas da deep_research (se houver)
const linhasBrutas = $input.all();

// 3. INICIALIZA O AGRUPADOR COM TODOS OS 13 SUBTÓPICOS OFICIAIS
const dadosAgrupados = {};

subtopicosOriginais.forEach(item => {
  const pIdRaw = item.json.passo_id;
  if (pIdRaw) {
    const match = String(pIdRaw).toLowerCase().match(/\d+[a-z]/);
    const key = match ? match[0] : String(pIdRaw).trim().toLowerCase();

    dadosAgrupados[key] = {
      passo_id: key,
      id_pesquisa: item.json.id_pesquisa || null,
      topico_principal: item.json.topico_principal || "",
      descricao: item.json.descricao_subtopico || "Descrição não encontrada",
      status: item.json.status || "",
      informacoes: []
    };
  }
});

// 4. Popula as informações garimpadas vindas da deep_research nas chaves já existentes
linhasBrutas.forEach(item => {
  const json = item.json;
  const rawRef = json.passo_id || json.topico_referencia || "";
  const match = String(rawRef).toLowerCase().match(/\d+[a-z]/);
  if (!match) return;

  const ref = match[0];

  // Adiciona a informação garimpada ao subtópico correspondente
  if (dadosAgrupados[ref] && json.informacao_resumida) {
    dadosAgrupados[ref].informacoes.push(json.informacao_resumida);
  }
});

// 5. Ordena as chaves dos subtópicos (1a, 1b, 2a, 3a...)
const refsOrdenadas = Object.keys(dadosAgrupados).sort((a, b) => {
  const matchA = a.match(/\d+/);
  const matchB = b.match(/\d+/);

  const numA = matchA ? parseInt(matchA[0]) : 0;
  const numB = matchB ? parseInt(matchB[0]) : 0;

  if (numA !== numB) return numA - numB;
  return a.localeCompare(b);
});

// 6. Monta a saída garantindo QUE TODOS OS 13 SUBTÓPICOS VÃO PARA O AUDITOR
const outputItems = refsOrdenadas.map(ref => {
  const sub = dadosAgrupados[ref];

  let infoFormatada = "";
  if (sub.informacoes.length > 0) {
    const infoUnicas = [...new Set(sub.informacoes)];
    infoFormatada = infoUnicas.map(info => `- ${info}`).join('\n');
  } else {
    infoFormatada = "- Nenhuma informação foi garimpada para este tópico.";
  }

  return {
    json: {
      id_pesquisa: sub.id_pesquisa,
      topico_principal: sub.topico_principal,
      passo_id: sub.passo_id,
      subtopico: `(${sub.passo_id}) ${sub.descricao}`,
      status_atual: sub.status,
      informacao_resumida_desse_subtopico: infoFormatada
    }
  };
});

return outputItems;

// 1. Pega todos os itens da entrada (linhas da status_pesquisa)
const items = $input.all();

if (items.length === 0) {
  return [];
}

// 2. Verifica se 100% dos itens possuem exatamente o status "auditar" E não estão processando
const todosProntosParaAuditar = items.every(item => 
  item.json.status === 'ok' && 
  item.json.Processando === false
);

// 3. Se faltar qualquer um (ex: status 'pendente', ou Processando: true), encerra em silêncio (retorna array vazio)
if (!todosProntosParaAuditar) {
  return [];
}

// 4. Se TODOS estiverem como "auditar" e Processando false, pega o id_pesquisa do primeiro item
const idPesquisa = items[0].json.id_pesquisa;

// 5. Retorna UM ÚNICO ITEM contendo o id_pesquisa para liberar os próximos nós
return [
  {
    json: {
      id_pesquisa: idPesquisa,
      total_subtopicos: items.length,
      status_geral: "todos_prontos_para_auditar"
    }
  }
];

